mapper.update:
UPDATE ddc_service_observation SET observed_at = #{row.observedAt}, valid_until = #{row.validUntil},
    recorded_at = #{row.recordedAt}, writer_epoch = #{row.writerEpoch}, report_seq = #{row.reportSeq},
    view_json = #{row.viewJson,jdbcType=OTHER,typeHandler=top.egon.cola.component.tianshu.admin.dao.typehandler.DdcJsonbTypeHandler},
    update_user_id = #{row.updateUserId}, update_time = #{row.updateTime}, version = version + 1
WHERE tenant_id = #{row.tenantId} AND id = #{row.id} AND version = #{expectedVersion} AND deleted_at IS NULL
    AND identity_tenant_id = #{row.identityTenantId} AND binding_id = #{row.bindingId}
    AND binding_revision = #{row.bindingRevision} AND binding_fingerprint = #{row.bindingFingerprint}
    AND cluster_id = #{row.clusterId} AND k8s_namespace = #{row.k8sNamespace}
    AND service_name = #{row.serviceName} AND service_uid = #{row.serviceUid}
    AND port_name = #{row.portName} AND service_port = #{row.servicePort}
    AND writer_epoch = #{expectedEpoch} AND report_seq = #{expectedSeq}
    AND (#{row.writerEpoch} > #{expectedEpoch}
        OR (#{row.writerEpoch} = #{expectedEpoch} AND #{row.reportSeq} > #{expectedSeq}))
